import assert from 'node:assert/strict';
import { AnthropicProvider } from './providers/anthropic.ts';
import { globalRegistry } from './providers/registry.ts';
import { handleMultiAgentChatRequest } from './handlers/multiAgentChat.ts';
const bodies: any[] = [];
const events = (items: any[]) => items.map(x => `data: ${JSON.stringify(x)}\n\n`).join('');
globalThis.fetch = (async (_url: any, init: any) => {
  const body = JSON.parse(init.body); bodies.push(body);
  const stream = bodies.length === 1 ? events([
    {type:'content_block_start',index:0,content_block:{type:'tool_use',id:'tool-123',name:'delegate_task'}},
    {type:'content_block_delta',index:0,delta:{type:'input_json_delta',partial_json:JSON.stringify({agent_id:'child-roundtrip',instructions:'Investigate'})}},
    {type:'content_block_stop',index:0}, {type:'message_stop'}
  ]) : events([{type:'content_block_delta',delta:{text:'Final answer'}},{type:'message_stop'}]);
  return new Response(stream);
}) as any;
globalRegistry.registerProvider(new AnthropicProvider('test'));
globalRegistry.registerProvider({id:'child-provider',name:'child',type:'openai',supportsImages:()=>false,async *executeChat(request) { assert.equal(request.message,'Investigate'); yield {type:'text',content:'Found it'}; yield {type:'done'}; }});
globalRegistry.registerAgent({id:'parent-roundtrip',name:'parent',description:'parent',provider:'anthropic'});
globalRegistry.registerAgent({id:'child-roundtrip',name:'child',description:'child',provider:'child-provider'});
const context: any = {req:{json:async()=>({message:'@parent-roundtrip start',requestId:'r'})},var:{config:{debugMode:false}}};
const response = await handleMultiAgentChatRequest(context,new Map());
const chunks = (await response.text()).trim().split('\n').map(JSON.parse);
assert.equal(bodies.length,2);
assert.equal(bodies[0].tools[0].name,'delegate_task');
assert.equal(bodies[1].messages[0].content[0].text,'@parent-roundtrip start');
assert.equal(bodies[1].messages[1].content[0].id,'tool-123');
assert.deepEqual(bodies[1].messages[2].content[0],{type:'tool_result',is_error:false,content:'Found it',tool_use_id:'tool-123'});
assert(chunks.some((c:any)=>c.data?.content==='Final answer'));
console.log('Provider round trip passed');
